            row.record.name ?? "",
            row.record.label ?? "",
            row.record.type ?? "",
            row.record.length ?? "",
            row.record.position ?? "",
            row.record.field_format ?? "",
            this.formatReferenceDisplay(row.record.ref),
            row.record.notes ?? ""
